(()=>{'use strict';
const $=s=>document.querySelector(s),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
let ko={},mine=null,busy=false,active=0,ranking=Array(7).fill('');
const units=CoopData.demonsIn('supreme'),name=slug=>{const d=CoopData.DEMON_BY_SLUG.get(slug);return ko[d?.name]||d?.name||slug;};
function portrait(slug){const img=el('img');img.src='/assets/units/'+CoopData.DEMON_BY_SLUG.get(slug).img+'.webp';img.alt=name(slug);return img;}
function sync(){const host=$('#vote-choices');host.replaceChildren();ranking.forEach((slug,i)=>{const button=el('button',undefined,'vote-rank-slot'+(active===i?' active':''));button.type='button';button.disabled=busy;button.setAttribute('aria-label',`${i+1}위 ${slug?name(slug)+' 변경':'초마신 선택'}`);button.setAttribute('aria-pressed',String(active===i));button.append(el('strong',`${i+1}위 · ${7-i}점`));button.append(slug?portrait(slug):el('span','＋','vote-rank-empty'));button.append(el('span',slug?name(slug):'초마신 선택'));button.onclick=()=>{active=i;$('#vote-picker').hidden=false;sync();};host.append(button);});
const candidates=$('#vote-candidates');candidates.replaceChildren();$('#vote-picker-title').textContent=`${active+1}위 초마신 선택`;
for(const d of [...units].sort((a,b)=>name(a.slug).localeCompare(name(b.slug),'ko'))){const chosen=ranking.indexOf(d.slug),button=el('button',undefined,'vote-candidate');button.type='button';button.disabled=busy||(chosen!==-1&&chosen!==active);button.setAttribute('aria-label',name(d.slug)+(chosen===-1?' 선택':` · ${chosen+1}위 선택됨`));button.append(portrait(d.slug),el('b',name(d.slug)),el('small',chosen===-1?'선택하기':`${chosen+1}위 선택됨`));button.onclick=()=>{ranking[active]=d.slug;const next=ranking.indexOf('');if(next!==-1)active=next;else $('#vote-picker').hidden=true;sync();};candidates.append(button);}
$('#vote-submit').disabled=busy||ranking.some(v=>!v)||new Set(ranking).size!==7;$('#vote-refresh').disabled=busy;$('#vote-submit').textContent=mine?'이 순위로 투표 수정하기':'이 순위로 투표하기';}
function showEditor(show){$('#vote-editor').hidden=!show;$('#vote-open').setAttribute('aria-expanded',String(show));if(show){active=Math.max(0,ranking.indexOf(''));$('#vote-picker').hidden=false;sync();$('#vote-editor').scrollIntoView?.({behavior:'smooth',block:'start'});}else $('#vote-open').focus?.();}
function render(data){mine=data.mine;$('#vote-total').textContent=`총 ${data.total.toLocaleString('ko-KR')}표 · 투표를 수정하면 기존 표를 대체합니다.`;const board=$('#dealer-tier-board');board.replaceChildren();if(!data.total)board.append(el('p','아직 투표가 없습니다. 첫 투표를 남겨 주세요.'));for(const tier of ['S','A','B','C','D','미득표']){const group=data.rows.filter(r=>r.tier===tier),row=el('section',undefined,'dealer-tier-row'),label=el('div',tier,'dealer-tier-label'),cards=el('div',undefined,'dealer-tier-cards');label.style.setProperty('--tier-color',({S:'#d86f86',A:'#e5a64f',B:'#6e9bd2',C:'#7eae87',D:'#a49baa'})[tier]||'#aaa');for(const r of group){const card=el('article',undefined,'dealer-tier-card');card.append(portrait(r.slug),el('b',name(r.slug)),el('small',r.score+'점 · '+r.votes+'표'));cards.append(card);}if(!group.length)cards.append(el('span','해당 캐릭터 없음','dealer-tier-empty'));row.append(label,cards);board.append(row);}}

async function load(write=false){if(busy)return;busy=true;sync();$('#vote-status').textContent=write?'투표를 저장하는 중…':'결과를 불러오는 중…';try{const response=await fetch('/api/tier-votes',write?{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({ranking})}:{cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(data.error||'투표 서버에 연결할 수 없습니다.');render(data);if(mine)ranking=Array.from(mine);$('#vote-status').textContent=write?'투표를 반영했습니다.':mine?'기존 투표를 불러왔습니다. 순서를 바꿔 수정할 수 있습니다.':'좋아하는 캐릭터 7종을 선택해 주세요.';if(write){showEditor(false);$('#vote-total').textContent+=' 투표를 반영했습니다.';}}catch(error){$('#vote-status').textContent=error.message;}finally{busy=false;sync();}}
$('#vote-open').onclick=()=>showEditor(true);$('#vote-close').onclick=()=>showEditor(false);$('#tier-ballot').onsubmit=e=>{e.preventDefault();if(!$('#vote-submit').disabled)load(true);};$('#vote-refresh').onclick=()=>load();
fetch('/ko.json').then(r=>r.json()).then(d=>ko=d).catch(()=>{}).finally(()=>{sync();load();if(new URLSearchParams(location.search).get('vote')==='1')showEditor(true);});
})();
